"use strict";

// Where a hotel's coordinates came from. "sample" = generated around real
// landmarks by scripts/backfillHotelData.js (the sample hotels are fictional);
// "exact" = a real address/position. Answers about distances and nearby
// places say "approximate" for sample locations instead of sounding exact.

module.exports = {
  async up(queryInterface, Sequelize) {
    await queryInterface.addColumn("Hotels", "locationSource", {
      type: Sequelize.ENUM("sample", "exact"),
      allowNull: true,
    });

    // Every location so far was generated by the backfill.
    await queryInterface.sequelize.query(
      "UPDATE Hotels SET locationSource = 'sample' WHERE latitude IS NOT NULL"
    );
  },

  async down(queryInterface) {
    await queryInterface.removeColumn("Hotels", "locationSource");
  },
};
